#include <omp.h>

/* Count the number of pixels in image with each grayscale intensity.
   The vector `image` is a grayscale image with values 0-255.
   Store the results in `bins`.
   Use OpenMP to count in parallel.
   Example:

   input: image=[2, 116, 201, 11, 92, 92, 201, 4, 2]
   output: [0, 0, 2, 0, 1, ...]
*/
 void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {

```cpp
#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    // Initialize output bins
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 256> local{};
        local.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < image.size(); ++i) {
            int v = image[i];
            if (v >= 0 && v < 256) {
                local[static_cast<std::size_t>(v)] += 1;
            }
            // If values may be out of range, they are ignored.
        }

        // Merge thread-local histograms safely
        #pragma omp critical
        {
            for (std::size_t b = 0; b < 256; ++b) {
                bins[b] += local[b];
            }
        }
    }
}
